/// <summary>
/// insert sales component charges
/// </summary>
Public abstract class METSalesPriceComponents
{
    SalesLine                           salesLine, selSalesLine;
    METSalesLinePriceComponentTmp       tmpTable;
    METSalesTable                       metSalesTabel;
    InventTransId                       inventTransId;
    SalesType                           salesType;

    public const int basePrice = 1;
    public const int margin = 2;
    public const int unitPrice = 3;
    public const int discount = 4;
    public const int netAmount = 5;
    public const int lineCharge = 6;

}

Method.Source:
/// <summary>
/// Return salestype.
/// </summary>
/// <param name = "_salesType">SalesType</param>
/// <returns>SalesType</returns>
public SalesType parmSalesType(SalesType _salesType = salesType)
{
    salesType = _salesType;

    return salesType;
}

/// <summary>
/// This method used for construct.
/// </summary>
/// <param name = "_salesType">SalesType</param>
/// <returns>METSalesPriceComponents</returns>
public static METSalesPriceComponents construct(SalesType _salesType)
{
    METSalesPriceComponents ret;        

    if (_salesType)
    {
        if (_salesType == SalesType::ReturnItem)
        {
            ret = new METSalesPriceComponents_Return();
        }
        else
        {
            ret = new METSalesPriceComponents_Sales();
        }

        ret.parmSalesType(_salesType);
    }

    return ret;
}

/// <summary>
/// This method used for query ranges.
/// </summary>
/// <param name = "qbdsSalesLine">QueryBuildDataSource</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_metSalesTabel">METSalesTable</param>
public abstract void queryRange(QueryBuildDataSource qbdsSalesLine, SalesLine _salesLine, METSalesTable _metSalesTabel)
{    
}

/// <summary>
/// This method used for set values.
/// </summary>
/// <param name = "_priceComponent">METSalesLinePriceComponent</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_tmpTable">METSalesLinePriceComponentTmp</param>
/// <param name = "_orgSalesLine">SalesLine</param>
public abstract void setValues(METSalesLinePriceComponent _priceComponent, SalesLine _salesLine, METSalesLinePriceComponentTmp _tmpTable, SalesLine _orgSalesLine)
{    
}

/// <summary>
/// Method to insert calculated records in temp table.
/// </summary>
/// <param name = "_salesLine">SalesLine</param>
/// <returns>METSalesLinePriceComponentTmp</returns>
public METSalesLinePriceComponentTmp insertTmp(SalesLine _salesLine)
{              
    salesLine = _salesLine;  
    if(salesType == SalesType::ReturnItem)
    {
        metSalesTabel   = METSalesTable::findBySalesId(_salesLine.SalesId);
    }

    this.insertReturnTemp();

    return tmpTable; 
}

/// <summary>
/// insert temparary table
/// </summary>
public void insertReturnTemp()
{
    RecordInsertList tmpRecordInsertList = new RecordInsertList(tableNum(METSalesLinePriceComponentTmp), false, false, false, false, false, tmpTable);

    Query query = new Query();
    QueryBuildDataSource qbdsSalesLine = this.buildQuery(query);    

    this.TempData(query, tmpRecordInsertList);

    tmpRecordInsertList.insertDatabase();
}

/// <summary>
/// buid query
/// </summary>
/// <param name = "_query">Query</param>
/// <returns>QueryBuildDataSource</returns>
private QueryBuildDataSource buildQuery(Query _query)
{
    QueryBuildDataSource qbdsParent = _query.addDataSource(tableNum(METSalesLinePriceComponent));
    QueryBuildDataSource qbdsSalesLine = qbdsParent.addDataSource(tableNum(SalesLine));

    qbdsSalesLine.joinMode(JoinMode::InnerJoin);
    qbdsSalesLine.addLink(fieldNum(SalesLine, InventTransId), fieldNum(METSalesLinePriceComponent, InventTransId));

    this.queryRange(qbdsSalesLine, salesLine, metSalesTabel);

    return qbdsSalesLine;
}

/// <summary>
/// This method used for process data into Tmp.
/// </summary>
/// <param name = "_query">Query</param>
/// <param name = "_insertList">RecordInsertList</param>
private void tempData(Query _query, RecordInsertList _insertList)
{
    QueryRun qr = new QueryRun(_query);
    METSalesLinePriceComponent salesLinePriceComponent;
    METPriceComponent priceComponent;
    Amount unitPriceAmount = 0, extPriceAmount = 0, discountValueAmount = 0, discountExtValueAmount = 0;
    boolean recordInserted = false;

    while (qr.next())
    {
        salesLinePriceComponent = qr.get(tablenum(METSalesLinePriceComponent));
        selSalesLine = qr.get(tablenum(SalesLine));

        inventTransId           = selSalesLine.InventTransId;
        tmpTable.InventTransId  = salesLinePriceComponent.InventTransId;
        tmpTable.Component      = salesLinePriceComponent.Component;
        tmpTable.PriceCodeRef   = salesLinePriceComponent.PriceCodeRef;
        tmpTable.FeeCode        = salesLinePriceComponent.FeeCode;
        tmpTable.PriceComponent = METComponentCode::findComponent(tmpTable.Component).PriceComponent;

        this.setValues(salesLinePriceComponent, salesLine, tmpTable, selSalesLine);

        priceComponent = METComponentCode::findComponent(salesLinePriceComponent.Component).PriceComponent;

        switch (priceComponent)
        {
            case METPriceComponent::BasePrice:
                tmpTable.LineNum = basePrice;
                unitPriceAmount  += tmpTable.Value;
                extPriceAmount   += tmpTable.ExtValue;
                break;

            case METPriceComponent::Discounts:
                tmpTable.LineNum        = discount;
                discountValueAmount     += tmpTable.Value;
                discountExtValueAmount  += tmpTable.ExtValue;
                break;

            case METPriceComponent::LineCharges:
                tmpTable.LineNum = lineCharge;
                break;

            case METPriceComponent::Margins:
                tmpTable.LineNum = margin;
                unitPriceAmount  += tmpTable.Value;
                extPriceAmount   += tmpTable.ExtValue;
                break;
        }

        _insertList.add(tmpTable);
        tmpTable.clear();

        recordInserted = true;
    }

    if (recordInserted)
    {
        tmpTable.InventTransId = salesLinePriceComponent.InventTransId;
        tmpTable.PriceComponent = METPriceComponent::UnitPrice;
        tmpTable.Value      = unitPriceAmount;
        tmpTable.ExtValue   = extPriceAmount;
        tmpTable.LineNum    = unitPrice;
        _insertList.add(tmpTable);
        tmpTable.clear();

        tmpTable.InventTransId  = salesLinePriceComponent.InventTransId;
        tmpTable.PriceComponent = METPriceComponent::NetAmount;
        tmpTable.Value          = unitPriceAmount - discountValueAmount;
        tmpTable.ExtValue       = extPriceAmount - discountExtValueAmount;
        tmpTable.LineNum        = netAmount;
        _insertList.add(tmpTable);
        tmpTable.clear();
    }
}

/// <summary>
/// get invent transid from original sales order
/// </summary>
/// <param name = "_salesLine">SalesLine</param>
/// <returns>InventTransId</returns>
public static InventTransId getInventTransID(SalesLine _salesLine)
{
    SalesLine     selSalesLine;
    METSalesTable metSalesTable = METSalesTable::findBySalesId(_salesLine.SalesId);

    select InventTransId from selSalesLine
        where selSalesLine.SalesId == metSalesTable.ParentClaimId
            && selSalesLine.ItemId == _salesLine.ItemId;

    return selSalesLine.InventTransId;
}
